''metadata'',''updated_at''])\n AND EXISTS(SELECT FROM gridex_ediel_retention.blob_tombstones t WHERE t.retention_class=''received_ediel_message_content'' AND t.target_id=oldrow.id AND t.company_id=oldrow.company_id AND t.source_hash=encode(sha256(convert_to(oldrow.raw_payload,''UTF8'')),''hex'') AND t.public_content_hash=encode(sha256(convert_to(gridex_ediel_retention.public_content_v1(oldrow)::text,''UTF8'')),''hex''))\n"},{"signature":"public.gridex_actor_has_company_permission(uuid,uuid,text)","body":"\n  select (p_actor_user_id is not null AND EXISTS(SELECT FROM public.permissions catalog WHERE catalog.key=p_permission AND catalog.is_active) and p_company_id is not null\n  and exists(\n    select 1 from auth.users u\n    where u.id = p_actor_user_id and u.deleted_at is null\n      and (u.banned_until is null or u.banned_until <= clock_timestamp())\n  )\n  and (\n    exists(\n      select 1 from public.admin_users au\n      where au.user_id = p_actor_user_id\n        and coalesce(au.is_active, true)\n        and lower(coalesce(au.role, '''')) in (''super_admin'', ''superadmin'', ''platform_superadmin'')\n    )\n    or exists(\n      select 1\n      from public.user_roles ur left join public.roles r on r.id = ur.role_id\n      where ur.user_id = p_actor_user_id and ur.company_id is null\n        and coalesce(ur.status, ''active'') = ''active'' and coalesce(ur.is_active, true)\n        and lower(coalesce(ur.role, r.key, r.name, '''')) in (''super_admin'', ''superadmin'', ''platform_superadmin'')\n    )\n    or (\n      exists(\n        select 1 from public.company_memberships cm\n        join public.companies c on c.id = cm.company_id\n        where cm.user_id = p_actor_user_id and cm.company_id = p_company_id\n          and coalesce(cm.status, ''active'') = ''active'' and coalesce(cm.is_active, true)\n          and coalesce(c.is_active, true)\n          and coalesce(c.status, ''active'') not in (''archived'', ''suspended'', ''pending_deletion'', ''deleted'')\n      )\n      and p_permission = any(\n        public.gridex_get_user_permissions_in_company(p_actor_user_id, p_company_id)\n      )\n    )\n  )\n  ) and not exists(\n    select 1 from public.user_permissions d left join public.permissions p on p.id=d.permission_id\n    where d.user_id=p_actor_user_id and (d.company_id is null or d.company_id=p_company_id)\n      and d.is_active and d.status=''active'' and d.effect=''deny''\n      and coalesce(nullif(d.permission_key,''''),p.key)=p_permission\n  ) and not exists(\n    select 1 from public.user_permission_overrides d\n    where d.user_id=p_actor_user_id and (d.company_id is null or d.company_id=p_company_id)\n      and d.is_active and d.effect=''deny'' and d.permission_key=p_permission\n      and (d.valid_from is null or d.valid_from<=clock_timestamp()) and (d.valid_to is null or clock_timestamp()<d.valid_to)\n  )\n","body_md5":"02c126207b21142e0de62563a287ea1e"},{"signature":"gridex_ediel_wire_namespace.before_message_write()","body":"\nBEGIN\n IF TG_OP=''UPDATE'' AND (NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.environment IS DISTINCT FROM OLD.environment OR NEW.direction IS DISTINCT FROM OLD.direction)\n  AND EXISTS(SELECT FROM gridex_ediel_wire_namespace.coverage WHERE source_message_id=OLD.id) THEN RAISE EXCEPTION ''ediel_wire_reference_namespace_context_immutable''; END IF;\n PERFORM gridex_ediel_wire_namespace.reserve(NEW);\n RETURN NEW;\nEND ","body_md5":"34f9d97c05f1805f4a3bea96256aa7a6"},{"signature":"gridex_ediel_wire_namespace.immutable()","body":"\nBEGIN RAISE EXCEPTION ''ediel_wire_reference_reservation_immutable''; END ","body_md5":"e56df235ff9099e5bfc6172ad536d9ec"},{"signature":"gridex_unattributed_intake.guard_original_v1()","body":"\nDECLARE mail_id uuid;old_mail_id uuid;old_json jsonb;new_json jsonb;\nBEGIN\n IF TG_TABLE_NAME=''ediel_messages'' THEN\n  IF NOT EXISTS(SELECT FROM gridex_unattributed_intake.technical_births WHERE source_message_id=OLD.id) THEN\n   IF TG_OP=''DELETE'' THEN RETURN OLD;END IF;RETURN NEW;\n  END IF;\n  IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''ediel_technical_intake_original_immutable'';END IF;\n  IF OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;\n  old_json:=to_jsonb(OLD)-ARRAY[''status'',''validation_report'',''contrl_status'',''aperak_status'',''utilts_err_status'',''ack_outcome'',\n   ''syntax_check_status'',''functional_check_status'',''failure_reason'',''parsed_at'',''validated_at'',''acknowledged_at'',''failed_at'',\n   ''ack_due_at'',''updated_at'',''updated_by'',''tenant_resolution_status'',''business_match_status'',''ack_status'',''processing_status'',\n   ''backend_automation_status'',''backend_automation_reason'',''contrl_due_at'',''business_response_due_at'',''response_overdue_at''];\n  new_json:=to_jsonb(NEW)-ARRAY[''status'',''validation_report'',''contrl_status'',''aperak_status'',''utilts_err_status'',''ack_outcome'',\n   ''syntax_check_status'',''functional_check_status'',''failure_reason'',''parsed_at'',''validated_at'',''acknowledged_at'',''failed_at'',\n   ''ack_due_at'',''updated_at'',''updated_by'',''tenant_resolution_status'',''business_match_status'',''ack_status'',''processing_status'',\n   ''backend_automation_status'',''backend_automation_reason'',''contrl_due_at'',''business_response_due_at'',''response_overdue_at''];\n  IF old_json IS DISTINCT FROM new_json OR gridex_unattributed_intake.is_birth_v1(NEW) IS NOT TRUE THEN\n   RAISE EXCEPTION ''ediel_technical_intake_original_immutable'' USING ERRCODE=''23514'';END IF;\n ELSE\n  IF TG_TABLE_NAME=''inbound_email_messages'' THEN mail_id:=OLD.id;\n  ELSE\n   IF TG_OP<>''DELETE'' THEN mail_id:=NEW.inbound_email_message_id;END IF;\n   IF TG_OP<>''INSERT'' THEN old_mail_id:=OLD.inbound_email_message_id;END IF;\n  END IF;\n  IF EXISTS(SELECT FROM gridex_unattributed_intake.technical_births WHERE inbound_email_message_id IN(mail_id,old_mail_id)) THEN\n   IF TG