  EXECUTE config#>>'{dispatcher,definition}';
  ALTER FUNCTION public.gridex_require_outbound_reply_basis_v1(public.ediel_messages) OWNER TO postgres;
  REVOKE ALL ON FUNCTION public.gridex_require_outbound_reply_basis_v1(public.ediel_messages) FROM PUBLIC,anon;
  GRANT EXECUTE ON FUNCTION public.gridex_require_outbound_reply_basis_v1(public.ediel_messages) TO service_role,authenticated;
 ELSIF dispatcher.prosrc<>config#>>'{dispatcher,body}' THEN
  definition:=pg_get_functiondef(dispatcher.oid);
  IF strpos(definition,dispatcher.prosrc)=0 THEN RAISE EXCEPTION 'existing_trigger_exact_dispatcher_definition_required';END IF;
  EXECUTE replace(definition,dispatcher.prosrc,config#>>'{dispatcher,body}');
  SELECT * INTO STRICT p_after FROM pg_proc WHERE oid=dispatcher.oid;
  IF (to_jsonb(p_after)-'prosrc') IS DISTINCT FROM (to_jsonb(dispatcher)-'prosrc') THEN RAISE EXCEPTION 'existing_trigger_dispatcher_identity_required';END IF;
 END IF;
 SELECT * INTO STRICT dispatcher FROM pg_proc WHERE oid=to_regprocedure(config#>>'{dispatcher,signature}');
 IF dispatcher.prosrc IS DISTINCT FROM config#>>'{dispatcher,body}' OR md5(dispatcher.prosrc) IS DISTINCT FROM config#>>'{dispatcher,body_md5}' OR dispatcher.proowner<>'postgres'::regrole::oid OR dispatcher.proacl::text IS DISTINCT FROM '{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}' OR dispatcher.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog'] OR dispatcher.provolatile<>'v' OR NOT dispatcher.prosecdef OR dispatcher.proisstrict OR dispatcher.proleakproof OR dispatcher.proparallel<>'u' OR dispatcher.procost<>100 OR dispatcher.prorows<>0 OR dispatcher.proargnames IS DISTINCT FROM ARRAY['m'] OR dispatcher.proargmodes IS NOT NULL OR dispatcher.prorettype<>'void'::regtype::oid OR dispatcher.pronargs<>1 OR dispatcher.proargtypes[0]<>'public.ediel_messages'::regtype::oid OR dispatcher.provariadic<>0 OR dispatcher.pronargdefaults<>0 OR dispatcher.proretset OR dispatcher.proallargtypes IS NOT NULL OR dispatcher.proargdefaults IS NOT NULL OR dispatcher.prosupport<>0 OR dispatcher.prokind<>'f' OR dispatcher.prolang<>(SELECT oid FROM pg_language WHERE lanname='plpgsql') OR has_function_privilege('anon',dispatcher.oid,'EXECUTE') OR NOT has_function_privilege('service_role',dispatcher.oid,'EXECUTE') OR NOT has_function_privilege('authenticated',dispatcher.oid,'EXECUTE') THEN RAISE EXCEPTION 'existing_trigger_exact_dispatcher_abi_acl_required';END IF;
 FOR spec IN SELECT value FROM jsonb_array_elements(config->'specs') LOOP
  SELECT * INTO STRICT p_before FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'signature');
  IF p_before.prosrc<>spec->>'after_body' THEN
   definition:=pg_get_functiondef(p_before.oid);
   IF strpos(definition,p_before.prosrc)=0 THEN RAISE EXCEPTION 'existing_trigger_exact_definition_required';END IF;
   EXECUTE replace(definition,p_before.prosrc,spec->>'after_body');
  END IF;
  SELECT * INTO STRICT p_after FROM pg_catalog.pg_proc WHERE oid=p_before.oid;
  IF (to_jsonb(p_after)-'prosrc') IS DISTINCT FROM (to_jsonb(p_before)-'prosrc') OR md5(p_after.prosrc)<>spec->>'after' OR p_after.prosrc<>spec->>'after_body' THEN
   RAISE EXCEPTION 'existing_trigger_complete_identity_body_required';END IF;
 END LOOP;
END
$existing_trigger_forward$;
NOTIFY pgrst,'reload schema';
COMMIT;
